#include <iostream>

// Function prototype specifying default values for all 3 dimensions
unsigned int boxVolume(unsigned int length = 1, unsigned int width = 1, unsigned int height = 1);

int main() {
    // No arguments -- uses default values for all dimensions (1 * 1 * 1)
    std::cout << "The default box volume is: " << boxVolume() << "\n\n";

    // Specify length; default width and height (10 * 1 * 1)
    std::cout << "The volume of a box with length 10,\n"
              << "width 1 and height 1 is: " << boxVolume(10) << "\n\n";

    // Specify length and width; default height (10 * 5 * 1)
    std::cout << "The volume of a box with length 10,\n"
              << "width 5 and height 1 is: " << boxVolume(10, 5) << "\n\n";

    // Specify all arguments explicitly (10 * 5 * 2)
    std::cout << "The volume of a box with length 10,\n"
              << "width 5 and height 2 is: " << boxVolume(10, 5, 2) << "\n";

    return 0;
}

// Function definition -- do not repeat default argument values here
unsigned int boxVolume(unsigned int length, unsigned int width, unsigned int height) {
    return length * width * height;
}

#include <iostream>

// Global variable named number
int number = 7;

int main() {
    // Local variable named number of a different type
    double number = 10.5;

    // Display values of local and global variables
    std::cout << "Local double value of number = " << number
              << "\nGlobal int value of number = " << ::number << std::endl;

    return 0;
}

#include <iostream>

// Overloaded square function for int
int square(int x) {
    std::cout << "square of integer " << x << " is ";
    return x * x;
}

// Overloaded square function for double
double square(double y) {
    std::cout << "square of double " << y << " is ";
    return y * y;
}

int main() {
    // 7 is an int literal -> calls int square(int)
    std::cout << square(7) << "\n";

    // 7.5 is a double literal -> calls double square(double)
    std::cout << square(7.5) << "\n";

    return 0;
}
